UPDATE `quest_template` SET `Details`='Olá, jovem $Gcaçador:caçadora;. Tu me olha como quem entende do riscado para lidar com uma fera e treiná-la como sua mascote.$B$BProcure Grif Selvacuore em Kharanos, tchê. Ele pode colocar você no caminho certo para ganhar um ajudante.' WHERE `entry`=6075;
