UPDATE `quest_template` SET `Details`='Não deixa os olhões delas te enganarem, cara! Essas mordeliscas de água salgada são um perigo. Não dá pra pescar nem cinco minutos sem aqueles devoradores de peixe tamanho família arrebentarem a linha pra pegar a isca.$B$BFaz um favor pra mim e pro povo da Aldeia Revatusco: mata elas, cara.$B$BMata todas elas!' WHERE `entry`=7815;
