UPDATE `quest_template` SET `OfferRewardText`='Excelente! Agora eu posso voltar para a minha ... vagarosa ... caçada agora. Obrigado, $N.' WHERE `entry`=183;
UPDATE `quest_template` SET `OfferRewardText`='Muito obrigado, $N! Como eu estava dizendo, essas partes não servem mais para pessoas honestas, mas se as coisas melhorarem, então essa escritura nos permitirá recuperar nossa terra.$b$bEu não tenho muito a oferecer a você, mas aqui - leve isso.' WHERE `entry`=184;
UPDATE `quest_template` SET `OfferRewardText`='Muito bom, $n.  Você está pronto para seguir em frente.' WHERE `entry`=185;
UPDATE `quest_template` SET `OfferRewardText`='Estou impressionada, $c.  Você está progredindo muito bem.' WHERE `entry`=186;
UPDATE `quest_template` SET `OfferRewardText`='Impressionante. Eu acredito que você está quase pronto.' WHERE `entry`=187;
UPDATE `quest_template` SET `OfferRewardText`='Mais que impressionante! Você é um verdadeiro Mestre na caça a tigres $N!' WHERE `entry`=188;
UPDATE `quest_template` SET `OfferRewardText`='Oh excelente, excelente. Isso ajudará um pouco...$b$b<Ele para, resmungando sobre margens de lucro e custos...>$b$bO que? Você ainda esta aqui? Recompensa? Ah, claro ... claro, aqui, leve isso ... deve ser mais do que suficiente.' WHERE `entry`=189;
