UPDATE `quest_template` SET `OfferRewardText`='<O rei Magni bate o punho com raiva.>' WHERE `entry`=4361;
UPDATE `quest_template` SET `OfferRewardText`='<Princesa Bronzebeard chora a perda do Imperador Dagran Thaurissan.>$B$BPor que ???' WHERE `entry`=4362;
UPDATE `quest_template` SET `OfferRewardText`='O Rei Magni Bronzebeard está visivelmente chateado.$B$BParece que mesmo na morte, Thaurissan venceu.$B$BVocê está dispensado, $n. Antes de sair, você pode escolher sua recompensa no cofre real.$B$B<O Rei Bronzebeard afunda em seu trono para meditar sobre essa mudança bizarra de eventos.>' WHERE `entry`=4363;
