UPDATE `quest_template` SET `OfferRewardText`='Você recuperou o medalhão! Agora poderei deixar a capela e cumprir meu dever.$B$BEsse dever é matar a besta que ajudou a me corromper e muitos dos meus irmãos e irmãs, o Barão Rivendare!' WHERE `entry`=5122;
