UPDATE `quest_template` SET `OfferRewardText`='Eu duvidei da possibilidade de tal item existir. Isso certamente abre uma oportunidade incrível - uma que não devemos desperdiçar.$B$BPrepare-se, $n, pois o que estou prestes a pedir a você vai levá-lo para as profundezas do inferno.' WHERE `entry`=5461;
