UPDATE `quest_template` SET `OfferRewardText`='A Melizza disse que você apareceria. Muito obrigado por tirá-la daquela encrenca. Infelizmente ela já deve ter se metido em outra...' WHERE `entry`=6132;
UPDATE `quest_template` SET `OfferRewardText`='Eu quero acreditar que você não leu o registro. Nem mesmo você faria algo tão idiota...' WHERE `entry`=6133;
UPDATE `quest_template` SET `OfferRewardText`='Aí está! E parece que tem um outro tanto espalhado sobre você... Meio pegajoso, não é?$B$BBem, muito obrigado pelo esforço, $n. Isso aqui vale uma fortuna... Se eu conseguir convencer os centauros disso!' WHERE `entry`=6134;
