UPDATE `quest_template` SET `OfferRewardText`='Ho ho alô, aventureiro!$B$BOs goblins me disseram que você tem direito a um presente especial, e é com prazer que o entrego a você. Tome aqui, e tenha um maravilhoso Véu de Inverno hoje e sempre.' WHERE `entry`=7045;
