UPDATE `quest_template` SET `OfferRewardText`='Você me traz seu velho raptor, eu te dou um novo com garras recém afiadas! O novo raptor será tão rápido quanto o seu antigo, mas com um novo visual para ele. Você pode ver os raptores swift aqui para ver o que você terá que escolher.' WHERE `entry`=7664;
