UPDATE `quest_template` SET `OfferRewardText`='Sim! Estas são as partes do livro! Vamos começar então, $N.$B$BTroque cada terceira palavra com palavras do segundo capítulo... então troque todas as outras palavras com palavras do primeiro capítulo... Espere, eu entendi isso de trás pra frente?' WHERE `entry`=8279;
