UPDATE `quest_template` SET `OfferRewardText`='Assim como eu suspeitava. Posso decifrar palavras individuais nas tabuletas, mas elas parecem desprovidas de qualquer lógica ou significado. Não é desconhecido que o Twilight\'s Hammer usem um código para esconder o significado de seus textos; teremos que levar a alguém que saiba mais sobre esse tipo de coisa.' WHERE `entry`=8284;
