UPDATE `quest_template` SET `OfferRewardText`='Isso é excelente, $n. Eu diria que estou surpreso, mas sabia sem dúvida que você não nos decepcionaria.$B$BÉ uma honra conceder a você um dos Poderosos Holy Mightstones Use bem.' WHERE `entry`=8418;
