UPDATE `quest_template` SET `OfferRewardText`='Muito bem, $n.\r\n\r\nAgora que você está no espírito do festival, aceite este convite para a Moonglade!\r\n\r\nTenho certeza de que vai se divertir bastante se passar algum tempo lá. Temos comida, bebida, histórias e, claro... mais fogos de artifícios!\r\n\r\nAbra este convite enquanto estiver dentro do grande círculo de luz lunar para ser transportad$go:a; para Moonglade.' WHERE `entry`=8867;
