UPDATE `quest_template` SET `OfferRewardText`='Você fez bem, $n. Através destas derrotas incrementais, nós prevaleceremos contra esta ameaça renovada do Flagelo.$B$BDescanse e recupere, depois você deve voltar para a frente novamente, para não perdermos o terreno que ganhamos hoje.$B$BPara te ajudar em suas futuras batalhas, disponibilizaremos alguns de nossos itens especiais que podem ser obtidos com Necrotic Runes.' WHERE `entry`=9153;
