UPDATE `quest_template` SET `RequestItemsText`='Você encontrou uma versão doentia e corrompida do que parece ser uma planta songflower. Um odor pungente e doentio emana da planta. Ele precisa desesperadamente de algum tipo de tratamento para voltar ao normal.' WHERE `entry`=3363;
