UPDATE `quest_template` SET `RequestItemsText`='Você conseguiu os tablets da Profecia de Mosh\'aru, $n?$b$bQuando eu tiver os tablets em mãos, vou estudá-los e aprender a conter a essência do Hakkar!' WHERE `entry`=3527;
