UPDATE `quest_template` SET `RequestItemsText`='O Tribunal das Marés fica impaciente. Eles tentam acabar com essa guerra que se espalhou por todas as dimensões por eras. Meus irmãos estão ansiosos para ouvir notícias da gloriosa vitória sobre os odiados elementais do fogo. Você tem os Incendrites que eu preciso?' WHERE `entry`=6393;
