UPDATE `quest_template` SET `RequestItemsText`='Matar um soberano qiraji é um feito notável para um mortal, <name>. No entanto, eles são muitos e poderosos. Continue a derrotá-los para provar seu valor como campeão.' WHERE `entry`=8595;
